<body>
    <div class="welcomescreen" id="welcomeScreen">
        <div class="welcomecard">
            <div class="welcomelogo">BMW AI Asszisztens</div>
            <div class="welcomesubtitle">Intelligens segítség az Ön BMWjéhez</div>

            <div class="carinfocompact">
                <div class="infoitem">
                    <div class="infolabel">Modell</div>
                    <div class="infovalue">520d E60</div>
                </div>
                <div class="infoitem">
                    <div class="infolabel">Évjárat</div>
                    <div class="infovalue">2009</div>
                </div>
                <div class="infoitem">
                    <div class="infolabel">Motor</div>
                    <div class="infovalue">N47 2.0L</div>
                </div>
                <div class="infoitem">
                    <div class="infolabel">Teljesítmény</div>
                    <div class="infovalue">177 LE</div>
                </div>
            </div>

            <button class="startbutton" onclick="startChat()">
                Chat Indítása
            </button>
        </div>
    </div>

    <div class="chatcontainer" id="chatContainer">
        <div class="chatheader">
            <div class="chattitle">BMW AI Asszisztens</div>
            <button class="backbutton" onclick="backToWelcome()">
                ← Vissza
            </button>
        </div>

        <div class="messages" id="messages">
            <div class="message assistant">
                <div class="messagebubble">
                    Üdvözlöm! Én vagyok az Ön BMW 520d E60 szakértő asszisztense. Kérdezzen bármit az autójáról!
                </div>
            </div>
        </div>

        <div class="inputcontainer">
            <div class="inputwrapper">
                <input type="text" class="messageinput" id="messageInput" placeholder="Írja be kérdését...">
                <button class="sendbutton" id="sendButton" onclick="sendMessage()">
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokewidth="2">
                        <line x1="22" y1="2" x2="11" y2="13"></line>
                        <polygon points="22,2 15,22 11,13 2,9 22,2"></polygon>
                    </svg>
                </button>
            </div>
        </div>
    </div>

    <script>
        let isTyping = false;
        let chatStarted = false;

        function addHapticFeedback() {
            if (navigator.vibrate) {
                navigator.vibrate(10);
            }
        }

        function startChat() {
            addHapticFeedback();
            chatStarted = true;

            document.getElementById('welcomeScreen').classList.add('hidden');

            setTimeout(() => {
                document.getElementById('chatContainer').classList.add('active');
                document.getElementById('messageInput').focus();
            }, 400);
        }

        function backToWelcome() {
            addHapticFeedback();
            chatStarted = false;

            document.getElementById('chatContainer').classList.remove('active');

            setTimeout(() => {
                document.getElementById('welcomeScreen').classList.remove('hidden');

                // Üzenetek törlése
                const messagesContainer = document.getElementById('messages');
                messagesContainer.innerHTML = 
                    <div class="message assistant">
                        <div class="messagebubble">
                            Üdvözlöm! Én vagyok az Ön BMW 520d E60 szakértő asszisztense. Kérdezzen bármit az autójáról!
                        </div>
                    </div>
                ;
            }, 400);
        }

        function addMessage(content, isUser = false) {
            const messagesContainer = document.getElementById('messages');
            const messageDiv = document.createElement('div');
            messageDiv.className = message ${isUser ? 'user' : 'assistant'};

            const bubbleDiv = document.createElement('div');
            bubbleDiv.className = 'messagebubble';

            if (isUser) {
                bubbleDiv.textContent = content;
            } else {
                // Formázott szöveg megjelenítése
                bubbleDiv.innerHTML = content.replace(/\n/g, '<br>');
            }

            messageDiv.appendChild(bubbleDiv);
            messagesContainer.appendChild(messageDiv);

            scrollToBottom();
        }

        function showTypingIndicator() {
            if (isTyping) return;
            isTyping = true;

            const messagesContainer = document.getElementById('messages');
            const typingDiv = document.createElement('div');
            typingDiv.className = 'message assistant';
            typingDiv.id = 'typingindicator';

            const bubbleDiv = document.createElement('div');
            bubbleDiv.className = 'messagebubble typingindicator';
            bubbleDiv.innerHTML = '<div class="typingdot"></div><div class="typingdot"></div><div class="typingdot"></div>';

            typingDiv.appendChild(bubbleDiv);
            messagesContainer.appendChild(typingDiv);

            scrollToBottom();
        }

        function hideTypingIndicator() {
            const typingIndicator = document.getElementById('typingindicator');
            if (typingIndicator) {
                typingIndicator.remove();
            }
            isTyping = false;
        }

        async function sendMessage() {
            if (!chatStarted) return;

            const input = document.getElementById('messageInput');
            const sendButton = document.getElementById('sendButton');
            const message = input.value.trim();

            if (!message) return;

            addHapticFeedback();

            addMessage(message, true);
            input.value = '';
            sendButton.disabled = true;

            showTypingIndicator();

            try {
                const response = await fetch('/chat', {
                    method: 'POST',
                    headers: {
                        'ContentType': 'application/json',
                    },
                    body: JSON.stringify({ message: message })
                });

                const data = await response.json();

                hideTypingIndicator();

                if (data.success) {
                    addMessage(data.response);
                } else {
                    addMessage('Sajnálom, hiba történt. Kérem próbálja újra!');
                }
            } catch (error) {
                hideTypingIndicator();
                addMessage('Kapcsolati hiba. Ellenőrizze az internetkapcsolatot!');
            }

            sendButton.disabled = false;
            input.focus();
        }

        function scrollToBottom() {
            const messagesContainer = document.getElementById('messages');
            messagesContainer.scrollTop = messagesContainer.scrollHeight;
        }

        document.getElementById('messageInput').addEventListener('keypress', function(e) {
            if (e.key === 'Enter' && chatStarted) {
                sendMessage();
            }
        });

        document.getElementById('sendButton').addEventListener('touchstart', addHapticFeedback);

        document.addEventListener('DOMContentLoaded', function() {
            // Kezdőképernyő megjelenítése
        });

        document.addEventListener('touchstart', function() {}, true);
    </script>
</body>
</html>

